class RecordsScreen extends ConsumerStatefulWidget {
  const RecordsScreen({super.key});

  @override
  ConsumerState<RecordsScreen> createState() => _RecordsScreenState();
}

class _RecordsScreenState extends ConsumerState<RecordsScreen> {
  String? _selectedMemberId;
  bool _readOnlyAdult = false;
  String _query = '';
  String _type = 'All';
  bool _newestFirst = true;

  List<HealthRecord> _filtered(List<HealthRecord> records) {
    final result = records.where((record) {
      final matchesQuery = record.title.toLowerCase().contains(
        _query.toLowerCase(),
      );
      final matchesType = _type == 'All' || record.type == _type;
      return matchesQuery && matchesType;
    }).toList();
    result.sort(
      (a, b) => _newestFirst
          ? b.recordedAt.compareTo(a.recordedAt)
          : a.recordedAt.compareTo(b.recordedAt),
    );
    return result;
  }

  Future<void> _toggleRecord(HealthRecord record) async {
    try {
      await ref
          .read(mobileApiProvider)
          .setRecordSharing(
            recordId: record.id,
            shared: !record.sharedWithFamilyHead,
          );
      ref.invalidate(memberRecordsProvider);
      ref.invalidate(recordsByMemberProvider);
    } catch (_) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Sharing could not be changed. Retry.')),
        );
      }
    }
  }

  Future<void> _toggleReport(LabReport report) async {
    try {
      await ref
          .read(mobileApiProvider)
          .setLabReportSharing(
            reportId: report.id,
            shared: !report.sharedWithFamilyHead,
          );
      ref.invalidate(memberLabReportsProvider);
      ref.invalidate(labReportsByMemberProvider);
    } catch (_) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Sharing could not be changed. Retry.')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    ref.listen<String?>(activeMemberProvider, (previous, next) {
      if (previous != next && _selectedMemberId != null) {
        setState(() {
          _selectedMemberId = null;
          _readOnlyAdult = false;
          _query = '';
          _type = 'All';
        });
      }
    });
    final dashboard = ref.watch(familyDashboardProvider).valueOrNull;
    final selected = dashboard?.isHead == true ? _selectedMemberId : null;
    final readOnly = dashboard?.isHead == true && _readOnlyAdult;
    final records = selected == null
        ? ref.watch(memberRecordsProvider)
        : ref.watch(recordsByMemberProvider(selected));
    final myMemberId = ref.watch(myMemberIdProvider).valueOrNull;
    return DefaultTabController(
      length: 2,
      child: Scaffold(
        appBar: AppBar(
          title: const Text('Health records'),
          bottom: const TabBar(
            tabs: [
              Tab(text: 'Records'),
              Tab(text: 'Lab reports'),
            ],
          ),
          actions: [
            if (!readOnly)
              IconButton(
                tooltip: 'Add record',
                onPressed: () => context.push('/records/new'),
                icon: const Icon(Icons.note_add_outlined),
              ),
            if (!readOnly)
              IconButton(
                tooltip: 'Upload lab report',
                onPressed: () => context.push('/lab-upload'),
                icon: const Icon(Icons.document_scanner_outlined),
              ),
          ],
        ),
        body: SafeArea(
          child: Column(
            children: [
              if (dashboard?.isHead == true && dashboard?.familyId != null)
                ref
                    .watch(recordsRosterProvider(dashboard!.familyId!))
                    .when(
                      loading: () => const LinearProgressIndicator(),
                      error: (_, _) => TextButton(
                        onPressed: () => ref.invalidate(
                          recordsRosterProvider(dashboard.familyId!),
                        ),
                        child: const Text('Retry member list'),
                      ),
                      data: (roster) => Padding(
                        padding: const EdgeInsets.all(16),
                        child: DropdownButtonFormField<String>(
                          key: ValueKey(
                            'records-member:${selected ?? ref.watch(activeMemberProvider)}',
                          ),
                          initialValue:
                              roster.any(
                                (member) =>
                                    member.id ==
                                    (selected ??
                                        ref.watch(activeMemberProvider)),
                              )
                              ? selected ?? ref.watch(activeMemberProvider)
                              : null,
                          isExpanded: true,
                          decoration: const InputDecoration(
                            labelText: 'Viewing health records',
                            prefixIcon: Icon(Icons.person_outline),
                          ),
                          items: [
                            for (final member in roster)
                              DropdownMenuItem(
                                value: member.id,
                                child: Text(
                                  '${member.displayName}${member.isSelf
                                      ? ' (You)'
                                      : member.isMinor
                                      ? ' (Minor)'
                                      : ' · Shared records'}',
                                  overflow: TextOverflow.ellipsis,
                                ),
                              ),
                          ],
                          onChanged: (id) {
                            if (id == null) return;
                            final member = roster.firstWhere(
                              (member) => member.id == id,
                            );
                            if (member.isSelf || member.isMinor) {
                              ref.read(activeMemberProvider.notifier).state =
                                  id;
                            }
                            setState(() {
                              _selectedMemberId = id;
                              _readOnlyAdult =
                                  !member.isSelf && !member.isMinor;
                              _query = '';
                              _type = 'All';
                            });
                          },
                        ),
                      ),
                    ),
              if (readOnly)
                const Padding(
                  padding: EdgeInsets.fromLTRB(16, 0, 16, 12),
                  child: Text(
                    'Read-only · Only records shared with the Family Head are available.',
                  ),
                ),
              Expanded(
                child: TabBarView(
                  children: [
                    records.when(
                      loading: () =>
                          const LoadingStateView(label: 'Loading records'),
                      error: (_, _) => ErrorRetryView(
                        onRetry: () {
                          if (selected == null) {
                            ref.invalidate(memberRecordsProvider);
                          } else {
                            ref.invalidate(recordsByMemberProvider(selected));
                          }
                        },
                      ),
                      data: (items) {
                        if (items.isEmpty) {
                          return const EmptyStateView(
                            title: 'No records yet',
                            message: 'No accessible records for this profile.',
                          );
                        }
                        final types = {
                          'All',
                          ...items.map((item) => item.type),
                        }.toList();
                        final visible = _filtered(items);
                        return Column(
                          children: [
                            Padding(
                              padding: const EdgeInsets.all(16),
                              child: Column(
                                children: [
                                  TextField(
                                    decoration: const InputDecoration(
                                      labelText: 'Search records',
                                      prefixIcon: Icon(Icons.search),
                                    ),
                                    onChanged: (value) =>
                                        setState(() => _query = value),
                                  ),
                                  const SizedBox(height: 12),
                                  Row(
                                    children: [
                                      Expanded(
                                        child: DropdownButtonFormField<String>(
                                          initialValue: _type,
                                          decoration: const InputDecoration(
                                            labelText: 'Type',
                                          ),
                                          items: [
                                            for (final type in types)
                                              DropdownMenuItem(
                                                value: type,
                                                child: Text(type),
                                              ),
                                          ],
                                          onChanged: (value) => setState(
                                            () => _type = value ?? 'All',
                                          ),
                                        ),
                                      ),
                                      const SizedBox(width: 12),
                                      IconButton.filledTonal(
                                        tooltip: _newestFirst
                                            ? 'Newest first'
                                            : 'Oldest first',
                                        onPressed: () => setState(
                                          () => _newestFirst = !_newestFirst,
                                        ),
                                        icon: Icon(
                                          _newestFirst
                                              ? Icons.arrow_downward
                                              : Icons.arrow_upward,
                                        ),
                                      ),
                                    ],
                                  ),
                                ],
                              ),
                            ),
                            Expanded(
                              child: visible.isEmpty
                                  ? const EmptyStateView(
                                      title: 'No matching records',
                                      message:
                                          'Change the search or type filter to see records.',
                                    )
                                  : ListView.builder(
                                      padding: const EdgeInsets.symmetric(
                                        horizontal: 16,
                                      ),
                                      itemCount: visible.length,
                                      itemBuilder: (context, index) {
                                        final record = visible[index];
                                        final meta = RecordSummaryMeta.parse(
                                          record.summary,
                                        );
                                        return Card(
                                          child: ListTile(
                                            leading: const Icon(
                                              Icons.description_outlined,
                                            ),
                                            title: Text(record.title),
                                            subtitle: Text(
                                              [
                                                '${record.type} · ${DateFormat.yMMMd().format(record.recordedAt)}',
                                                if (meta.metaLine.isNotEmpty)
                                                  meta.metaLine,
                                              ].join('\n'),
                                            ),
                                            isThreeLine:
                                                meta.metaLine.isNotEmpty,
                                            trailing:
                                                record.memberId == myMemberId
                                                ? IconButton(
                                                    tooltip:
                                                        record
                                                            .sharedWithFamilyHead
                                                        ? 'Shared with Family Head · make private'
                                                        : 'Private · share with Family Head',
                                                    onPressed: () =>
                                                        _toggleRecord(record),
                                                    icon: Icon(
                                                      record.sharedWithFamilyHead
                                                          ? Icons.people_outline
                                                          : Icons.lock_outline,
                                                    ),
                                                  )
                                                : null,
                                          ),
                                        );
                                      },
                                    ),
                            ),
                          ],
                        );
                      },
                    ),
                    _LabReportsTab(
                      key: ValueKey(
                        selected ?? ref.watch(activeMemberProvider),
                      ),
                      memberId: selected,
                      myMemberId: myMemberId,
                      onToggle: _toggleReport,
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _LabReportsTab extends ConsumerStatefulWidget {
  const _LabReportsTab({
    super.key,
    this.memberId,
    required this.myMemberId,
    required this.onToggle,
  });
  final String? memberId;

  final String? myMemberId;
  final Future<void> Function(LabReport report) onToggle;

  @override
  ConsumerState<_LabReportsTab> createState() => _LabReportsTabState();
}

class _LabReportsTabState extends ConsumerState<_LabReportsTab> {
  bool _grid = false;
  @override
  void dispose() {
    final route = _previewRoute;
    if (route?.isActive == true) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (route!.isActive) route.navigator?.removeRoute(route);
      });
    }
    super.dispose();
  }

  Route<void>? _previewRoute;
  Future<void> _viewOriginal(LabReport report, String? memberId) async {
    try {
      await showDialog<void>(
        context: context,
        builder: (dialogContext) {
          _previewRoute = ModalRoute.of(dialogContext);
          return OriginalReportPreviewDialog(
            fileName: report.fileName,
            load: () async {
              final bytes = await ref
                  .read(mobileApiProvider)
                  .getLabReportFile(report.id);
              if (!mounted ||
                  (widget.memberId ?? ref.read(activeMemberProvider)) !=
                      memberId) {
                throw StateError('Profile changed');
              }
              return bytes;
            },
          );
        },
      );
    } finally {
      _previewRoute = null;
    }
  }

  @override
  Widget build(BuildContext context) {
    ref.listen<String?>(activeMemberProvider, (previous, next) {
      if (previous != next && _previewRoute?.isActive == true) {
        Navigator.of(context).removeRoute(_previewRoute!);
        _previewRoute = null;
      }
    });
    final memberId = widget.memberId ?? ref.watch(activeMemberProvider);
    final reports = widget.memberId == null
        ? ref.watch(memberLabReportsProvider)
        : ref.watch(labReportsByMemberProvider(widget.memberId!));
    return reports.when(
      loading: () => const LoadingStateView(label: 'Loading lab reports'),
      error: (_, _) => ErrorRetryView(
        onRetry: () {
          if (widget.memberId == null) {
            ref.invalidate(memberLabReportsProvider);
          } else {
            ref.invalidate(labReportsByMemberProvider(widget.memberId!));
          }
        },
      ),
      data: (items) => items.isEmpty
          ? const EmptyStateView(
              title: 'No lab reports',
              message: 'Upload a synthetic lab report to start the library.',
            )
          : ListView(
              padding: const EdgeInsets.all(16),
              children: [
                Row(
                  children: [
                    Expanded(
                      child: Text(
                        '${items.length} reports',
                        style: Theme.of(context).textTheme.titleMedium,
                      ),
                    ),
                    IconButton(
                      tooltip: 'List view',
                      isSelected: !_grid,
                      onPressed: () => setState(() => _grid = false),
                      icon: const Icon(Icons.view_list_outlined),
                    ),
                    IconButton(
                      tooltip: 'Grid view',
                      isSelected: _grid,
                      onPressed: () => setState(() => _grid = true),
                      icon: const Icon(Icons.grid_view_outlined),
                    ),
                  ],
                ),
                const SizedBox(height: 12),
                LayoutBuilder(
                  builder: (context, constraints) => Wrap(
                    spacing: 12,
                    runSpacing: 12,
                    children: [
                      for (final report in items)
                        SizedBox(
                          width: _grid && constraints.maxWidth >= 340
                              ? (constraints.maxWidth - 12) / 2
                              : constraints.maxWidth,
                          child: ReportLibraryCard(
                            key: ValueKey('$memberId:${report.id}'),
                            compact: _grid,
                            loadOriginal: () async {
                              final bytes = await ref
                                  .read(mobileApiProvider)
                                  .getLabReportFile(report.id);
                              if (!mounted ||
                                  (widget.memberId ??
                                          ref.read(activeMemberProvider)) !=
                                      memberId) {
                                throw StateError('Profile changed');
                              }
                              return bytes;
                            },
                            report: report,
                            ownerName: report.memberId == widget.myMemberId
                                ? 'You'
                                : 'Family member',
                            canChangeSharing:
                                report.memberId == widget.myMemberId,
                            onToggleSharing: () => widget.onToggle(report),
                            onViewOriginal: () =>
                                _viewOriginal(report, memberId),
                          ),
                        ),
                    ],
                  ),
                ),
              ],
            ),
    );
  }
}
